import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class FileManager {
    private static final Map<String, Boolean> cachedThumbs = new HashMap<>();

    public static void cacheReceiveThumb(BaseFileInfo fileInfo, InputStream inputStream) throws IOException {
        if (fileInfo == null || inputStream == null) {
            return;
        }
        String key = getThumbKey(fileInfo);
        if (cachedThumbs.containsKey(key)) {
            return;
        }
        Path thumbPath = Paths.get("./thumbnails/" + fileInfo.getName() + ".png");
        Files.copy(inputStream, thumbPath, StandardCopyOption.REPLACE_EXISTING);
        cachedThumbs.put(key, true);
    }

    private static String getThumbKey(BaseFileInfo fileInfo) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] fileData = Files.readAllBytes(fileInfo.getFile().toPath());
            byte[] hash = md.digest(fileData);
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException | IOException e) {
            e.printStackTrace();
            return null;
        }
    }
}
```
