        }
    }
    return factorsList
}

fun getFactorsCombinations(n: Int): List<List<Int>> {
    if (n < 2 || n > 1e7.toInt()) {
        return emptyList()
    }

    val factors = factors(n)
    val combinations = mutableListOf<List<Int>>()

    fun dfs(start: Int, path: MutableList<Int>) {
        if (path.size > 1) {
            combinations.add(path.toList())
        }

        val currentProduct = path.reduce { acc, i -> acc * i }
        for (i in start until factors.size) {
            if (currentProduct > n) {
                break
